import {defineComponent,h,ref,onBeforeUnmount} from 'vue';
export const YkDropdownMenu=defineComponent({name:'YkDropdownMenu',props:{items:{type:Array,default:()=>[]}},emits:['select'],setup(p,{slots,emit}){const open=ref(false);const onDoc=e=>{if(!e.target.closest?.('.yk-dropdown'))open.value=false};if(typeof document!=='undefined')document.addEventListener('pointerdown',onDoc);onBeforeUnmount(()=>document.removeEventListener('pointerdown',onDoc));return()=>h('span',{class:'yk-dropdown'},[slots.trigger?.({open:open.value,toggle:()=>open.value=!open.value}),open.value?h('div',{class:'yk-dropdown__menu',role:'menu'},p.items.map(i=>h('button',{type:'button',role:'menuitem',disabled:i.disabled,onClick:()=>{emit('select',i);open.value=false}},i.label))):null]);}});
